package com.vandorlabs.neoforge.screen;

import com.vandorlabs.neoforge.credentials.NativeCredentialItems;
import com.vandorlabs.screen.*;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.world.level.GameType;

/** Selected chip persistence and authority through real installed private hosts; packet/ray acceptance is separate. */
final class ScreenChipHostChecks {
 private static int checks;
 private static final BlockPos BASE=new BlockPos(5440,100,5440);
 private static void need(boolean yes,String why){checks++;if(!yes)throw new AssertionError("Screen chip host: "+why);}
 private static CompoundTag original(ScreenFamily family,ServerLevel level){var tag=NativeScreenFactory.choices(family,NativeScreenCatalog.INSTANCE,NativeScreenCatalog.INSTANCE.defaultHousing(),NativeScreenCatalog.INSTANCE.defaultFrame());tag.putInt(family==ScreenFamily.HALF_CONSOLE?"SecondarySurfaceTexture":"PrimarySurfaceTexture",-4);tag.putInt("ChipDisplayPage",300);var chip=NativeCredentialItems.dataChip(2);var data=new CompoundTag();data.putString("PrivateItemMarker","private-"+"x".repeat(40000));chip.set(DataComponents.CUSTOM_DATA,CustomData.of(data));var entries=new String[8];java.util.Arrays.fill(entries,"\n".repeat(512));NativeChipJournal.write(chip,true,"Journal",entries);var reader=new CompoundTag();reader.put("InsertedToken",NativeCredentialItems.writeStack(chip,level.registryAccess()));tag.put("ScreenChipReader",reader);return tag;}
 static void run(ServerLevel level,java.util.Map<ScreenFamily,NativeScreenBlock> blocks,boolean read){
  var player=net.neoforged.neoforge.common.util.FakePlayerFactory.getMinecraft(level);player.setGameMode(GameType.SURVIVAL);
  for(var family:ScreenFamily.values()){var pos=BASE.east(family.ordinal()*3);level.getChunkAt(pos);if(!read){level.setBlock(pos,blocks.get(family).defaultBlockState(),2);var tile=(NativeScreenEntity)level.getBlockEntity(pos);var tag=original(family,level);var before=tag.copy();tile.loadWithComponents(tag,level.registryAccess());need(before.equals(tag)&&!tile.inert(),"known selected Source surface installs defensively "+family);need(tile.chipPage()==256,"released saved-page clamp "+family);var saved=tile.saveWithoutMetadata(level.registryAccess());need(saved.getInt("ChipDisplayPage")==256&&saved.getCompound("ScreenChipReader").contains("InsertedToken"),"complete selected owner saved "+family);var projection=tile.getUpdateTag(level.registryAccess());need(!projection.contains("ScreenChipReader")&&!projection.toString().contains("PrivateItemMarker")&&!projection.toString().contains("private-"),"public update excludes physical/private data "+family);need(projection.contains(NativeScreenChipService.VIEW)==ScreenChipMount.integrated(family),"only integrated ownership publishes reader display "+family);
    if(ScreenChipMount.integrated(family)){need(tile.chipView().reader.occupied()&&tile.chipView().page==256&&tile.chipView().journal.pages.size()==416,"bounded prepared selected journal "+family);need(tile.visual().chip()==tile.chipView(),"coherent visual and display publication "+family);var decoded=NativeScreenChipView.read(projection.getCompound(NativeScreenChipService.VIEW));need(decoded.journal.key.equals(tile.chipView().journal.key),"public display roundtrip "+family);player.getInventory().clearContent();player.setPos(pos.getX()+.5,pos.getY(),pos.getZ()+2);need(tile.chips().navigate(player,tile,tile.chipView(),1)&&tile.chipPage()==257,"live page advances beyond legacy saved clamp "+family);need(tile.chips().interact(player,InteractionHand.MAIN_HAND)&&!tile.chipView().reader.occupied()&&tile.chipPage()==0,"empty hand removes one chip/reset page "+family);int owned=0;ItemStack taken=ItemStack.EMPTY;for(var stack:player.getInventory().items)if(stack.is(NativeCredentialItems.DATA_CHIP.get())){owned+=stack.getCount();taken=stack.copy();}need(owned==1,"one usable removed owner "+family);player.getInventory().clearContent();player.setItemInHand(InteractionHand.MAIN_HAND,taken);need(tile.chips().interact(player,InteractionHand.MAIN_HAND)&&player.getMainHandItem().isEmpty()&&tile.chipView().reader.occupied()&&tile.chipPage()==0,"Survival reinsertion preserves sole owner "+family);var spare=pos.south(24);level.getChunkAt(spare);level.setBlock(spare,blocks.get(family).defaultBlockState(),2);var empty=(NativeScreenEntity)level.getBlockEntity(spare);var emptyTag=NativeScreenFactory.choices(family,NativeScreenCatalog.INSTANCE,NativeScreenCatalog.INSTANCE.defaultHousing(),NativeScreenCatalog.INSTANCE.defaultFrame());emptyTag.putInt(family==ScreenFamily.HALF_CONSOLE?"SecondarySurfaceTexture":"PrimarySurfaceTexture",-4);emptyTag.putInt("ChipDisplayPage",9);empty.loadWithComponents(emptyTag,level.registryAccess());player.setPos(spare.getX()+.5,spare.getY(),spare.getZ()+2);need(empty.chipPage()==9&&empty.chips().interact(player,InteractionHand.MAIN_HAND)&&empty.chipPage()==0&&!empty.chipView().reader.occupied(),"empty tray also consumes/reset saved page "+family);level.removeBlock(spare,false);}
    var future=tag.copy();future.putInt("PrimarySurfaceTexture",-3);var rejected=new NativeScreenEntity(tile.getType(),pos,tile.getBlockState(),family,NativeScreenCatalog.INSTANCE);rejected.loadWithComponents(future,level.registryAccess());need(rejected.inert()&&rejected.saveWithoutMetadata(level.registryAccess()).equals(future),"Vehicle selection remains original inert owner "+family);
   }else{var tile=(NativeScreenEntity)level.getBlockEntity(pos);need(tile!=null&&!tile.inert(),"selected surface survives restart "+family);var saved=tile.saveWithoutMetadata(level.registryAccess());var item=NativeCredentialItems.readStack(saved.getCompound("ScreenChipReader").getCompound("InsertedToken"),level.registryAccess());need(item.getCount()==1&&item.is(NativeCredentialItems.DATA_CHIP.get()),"exactly one saved physical owner "+family);need(tile.chipPage()==(ScreenChipMount.integrated(family)?0:256),"page saved independently of private inventory "+family);}
  }
  if(!read)surfaces(level,blocks);player.getInventory().clearContent();System.out.println("[vandorlabs][screen-chip-host] "+(read?"read":"write")+" PASS checks="+checks+" seven roles/selected ownership/private projection/saved pages; real player ray routing separate");
 }
 private static void surfaces(ServerLevel level,java.util.Map<ScreenFamily,NativeScreenBlock> blocks){
  var base=BASE.south(48);var members=new java.util.ArrayList<NativeScreenEntity>();var screen=blocks.get(ScreenFamily.SCREEN);for(int i=0;i<3;i++){var pos=base.east(i);level.getChunkAt(pos);level.setBlock(pos,screen.defaultBlockState(),2);var tile=(NativeScreenEntity)level.getBlockEntity(pos);var tag=NativeScreenFactory.choices(ScreenFamily.SCREEN,NativeScreenCatalog.INSTANCE,NativeScreenCatalog.INSTANCE.defaultHousing(),NativeScreenCatalog.INSTANCE.defaultFrame());tile.loadWithComponents(tag,level.registryAccess());members.add(tile);}
  var origin=members.get(0);var choice=new NativeScreenSurfaceEdit(0,-4);need(NativeScreenGroups.editMembers(origin).size()==3,"current Source edit rectangle before choosing Chip");need(!NativeScreenSurfaceGroups.apply(origin,choice,tile->true),"unattached regular Screen refuses Chip");
  var readerBlock=(com.vandorlabs.neoforge.credentials.NativeCredentialReaderBlock)net.minecraft.core.registries.BuiltInRegistries.BLOCK.get(net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("vandorlabs","reader_geometry_fixture_chip"));var readerPos=base.below();level.setBlock(readerPos,readerBlock.defaultBlockState().setValue(com.vandorlabs.neoforge.NativeMountedSwitchBlock.FACING,Direction.DOWN),2);var reader=(com.vandorlabs.neoforge.credentials.NativeCredentialReaderEntity)level.getBlockEntity(readerPos);reader.onLoad();need(NativeScreenChipInteractions.available(origin,0),"empty adjacent physical reader enables Chip choice");
  var before=members.stream().map(NativeScreenEntity::screenSettings).toList();need(!NativeScreenSurfaceGroups.apply(origin,choice,tile->tile!=members.get(2)),"one denied member refuses complete joined edit");for(int i=0;i<3;i++)need(members.get(i).screenSettings()==before.get(i),"denied rectangle leaves every scalar unchanged");
  need(NativeScreenSurfaceGroups.apply(origin,choice,tile->true),"accepted current rectangle chooses Chip");for(var tile:members)need(tile.screenSettings().primarySurface()==-4&&!tile.controls(0).enabled(),"all accepted members choose same raw surface");need(NativeScreenChipGroups.group(origin).members().size()==3,"post-selection rectangle remains joined");
  need(NativeScreenSurfaceGroups.apply(members.get(2),new NativeScreenSurfaceEdit(0,-1),tile->true),"nonowner leaves Chip for complete current rectangle");for(var tile:members)need(tile.screenSettings().primarySurface()==-1,"leaving Chip restores every member");level.removeBlock(readerPos,false);need(!NativeScreenSurfaceGroups.apply(origin,choice,tile->true),"removed reader withdraws current choice availability");
  for(var tile:members)level.removeBlock(tile.getBlockPos(),false);System.out.println("[vandorlabs][screen-chip-host] surface group PASS attached/empty/missing reader, denied member, nonowner selection and whole-layout withdrawal");
 }

}
